func Add() {
	switch answerbash {

	case "bash":

		stripcmd := switchutility.InputScanDirections("add a commnd..")
		inputnote := switchutility.InputScanDirections("add a description..")
		striptag := switchutility.InputScanDirections("add a tag..")
		stripbash := switchutility.InputScanDirections("what is the directory of bashfile?")
		stripbashname := switchutility.InputScanDirections("what is the name of bashfile?")

		bash := "true"
		if err := tags.Create(stripcmd, inputnote, striptag, bash, stripbash, stripbashname); err != nil {
			switchutility.Checklogger(err, "creating bash file")
		}

		if _, err := ff.Filefolder("."+stripbash, stripbashname+".bash"); err != nil {
			switchutility.Checklogger(err, "trying to create bash file")
		}

	case "custom":
		stripcmd := switchutility.InputScanDirections("add a commnd..")
		inputdesc := switchutility.InputScanDirections("add a description..")
		striptag := switchutility.InputScanDirections("add a tag..")

		bash := "false"

		if err := tags.Create(stripcmd, inputdesc, striptag, bash, "", ""); err != nil {
			switchutility.Checklogger(err, "creating bash file")
		}

		cmdcreator.Cmdcreator(stripcmd)

	"os"

	"github.com/golangast/switchterm/switchtermer/switchutility"

	"golang.org/x/text/cases"
	"golang.org/x/text/language"
)

func RemoveCMD(cmd string) {

	if err := switchutility.UpdateText("./switchtermer/cmd/cmdrunner/cmdrunner.go", `"github.com/golangast/switchterm/cmd/`+cmd+`"`, "", ""); err != nil {
		switchutility.Checklogger(err, "trying to update text in cmdrunner.go")
	}

	if err := switchutility.UpdateText("./switchtermer/cmd/cmdrunner/cmdrunner.go", `case "`+cmd+`"`+":"+"\n"+cmd+"."+cases.Title(language.Und, cases.NoLower).String(cmd)+"()", "", ""); err != nil {
		switchutility.Checklogger(err, "trying to remove call")
	}

	if err := os.RemoveAll("./cmd/" + cmd); err != nil {
		switchutility.Checklogger(err, "trying to remove folder")
	}

import (
	"errors"
	"fmt"
	"log/slog"
	"os"

	"github.com/golangast/gentil/utility/ff"
	"github.com/golangast/switchterm/loggers"
	"github.com/golangast/switchterm/switchtermer"
	"github.com/golangast/switchterm/switchtermer/db/createtable"
)

func main() {
	logger := loggers.CreateLogger()

	if _, err := os.Stat("./db/data.db"); errors.Is(err, os.ErrNotExist) {
		_, err := ff.Makefile("./db/data.db")
		if err != nil {
			fmt.Print(err)
		}

		err = createtable.CreateTable()
		if err != nil {
			logger.Error(
				"creating table",
				slog.String("error: ", err.Error()),
			)
		}

	}
